import{z as A,x as s,o as r,c as d,q as B,j as o,D as E,d as t,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"底层与粘附","description":"","frontmatter":{"title":"底层与粘附","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/underlayer-adhesion.md","filePath":"litho/underlayer-adhesion.md","lastUpdated":1791413859000}'),p={name:"litho/underlayer-adhesion.md"};function h(D,a,u,m,f,C){const l=s("Mermaid");return r(),d("div",null,[a[2]||(a[2]=B('<h1 id="底层与粘附" tabindex="-1">底层与粘附 <a class="header-anchor" href="#底层与粘附" aria-label="Permalink to &quot;底层与粘附&quot;">​</a></h1><div class="epigraph"><p>浮雕再直，底部剪应力一过黏附强度就剥。底层首先是界面能与机械锚，其次才是光学减反或二次电子源。</p><footer>—— 据 BARC / underlayer 与抗蚀剂黏附的产线叙述；EUV 底层功能栈见主干 underlayer 课</footer></div><p><a href="/litho/pab-solvent">上一课</a>把膜内溶剂赶到可重复。缺口是膜下界面：胶（或成像层）与 BARC / SOC / 无机硬掩模之间的黏附。主干 <a href="/litho/euv-underlayer">EUV 底层</a> 已从二次电子与隔离写过 EUV 栈。本课补的差是一般层的黏附力学与表面处理，不把那一课的电子产额再推导一遍。聚合物分子量如何改膜的内聚与溶解，留给<a href="/litho/resist-polymer-mw">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>显影液毛细力、冲洗、随后干法的剪应力，都作用在界面上。黏附不足：漂胶、剥落、局部「缺图形」，看起来像随机缺孔或扫描失焦。黏附过强且互溶：界面混合，footing、去胶残渣、BARC 开口困难。<a href="/litho/pattern-collapse">图形倒塌</a> 是高深宽比下的毛细力矩，黏附是它的边界条件——倒是体，剥是界面。</p><p>缺口不是再列 BARC 减反，而是：表面能、底涂（HMDS 一类）、底层交联密度，如何把「还贴着」写成可签核项。光学 BARC 选厚在反射极小，并不自动给出黏附极大。</p><p><span class="marginnote">常见误区：反射调到极小就以为万事大吉。实际反射极小点的厚度只管光学，黏附取决于表面能与交联状态——同一片可以既不反光又大片剥胶，两项必须分开签核。</span></p><h3 id="不要把-euv-电子灌入当成黏附" tabindex="-1">不要把 EUV 电子灌入当成黏附 <a class="header-anchor" href="#不要把-euv-电子灌入当成黏附" aria-label="Permalink to &quot;不要把 EUV 电子灌入当成黏附&quot;">​</a></h3><p>高 Z 底层抬灵敏度，是电子产额，不是黏附变好。黏附失败的片也可以很敏。分析要拆：重复性差的剥落跟涂胶头、底涂、等待湿度走；泊松缺孔跟剂量走。</p><p><span class="marginnote">HMDS 把氧化硅表面从亲水改成更匹配有机胶的润湿。过量或过烘反而生成弱界面层。底涂是资格项，不是「有或没有」开关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：划格、磁带、显影后高压冲洗、聚焦离子束看界面、刻蚀后剥落检查。表面：接触角、底涂温度时间、底层 PAB / 固化。光学与黏附联合：换 BARC 材料族时同时看反射与剥落，不要只盯 swing。</p><p>EUV 层沿用主干底层课的功能清单（黏附、隔离、电子、硬掩模），本课只强调：黏附规格在 DUV 与 EUV 上都是一等项，不因为「有 BARC」就自动满足。</p><p><span class="marginnote">「划格测试」就是用刀片在膜面划出一百个小方格、贴上胶带猛撕一下的土办法：撕掉的格子越少黏附越好。产线先用它快速筛掉明显不粘的层，再上显微镜做细判。</span></p>',14)),(r(),o(n,null,{default:E(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20SURF%5B%22%E8%A1%A8%E9%9D%A2%E8%83%BD%20%2F%20%E5%BA%95%E6%B6%82%22%5D%20--%3E%20ADH%5B%22%E7%95%8C%E9%9D%A2%E9%BB%8F%E9%99%84%22%5D%0A%20%20UL%5B%22%E5%BA%95%E5%B1%82%E5%9B%BA%E5%8C%96%20%2F%20%E4%BA%A4%E8%81%94%22%5D%20--%3E%20ADH%0A%20%20ADH%20--%3E%20HOLD%5B%22%E6%8A%97%E6%98%BE%E5%BD%B1%E6%AF%9B%E7%BB%86%E4%B8%8E%E5%B9%B2%E6%B3%95%E5%89%AA%22%5D%0A%20%20ADH%20--%3E%20FAIL%5B%22%E5%89%A5%E8%90%BD%20%2F%20footing%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"润湿不良则涂布空洞，显影从空洞撕开。润湿好但扩散互溶，形成混合层，\\(R(m)\\) 在底部失定义，出现 footing。底层过固化变玻璃，机械锚变差；欠固化则被显影液攻击。PAB 过狠让胶底部溶剂过低、收缩应力集中在界面，剥落在曝光前就已经埋下。",-1)),a[5]||(a[5]=e("p",null,[e("span",{class:"marginnote"},"「footing」指线条底部像穿了条裙子一样外扩：界面互溶时显影液把线底吃出坡脚，线宽在底部凭空多出几纳米——在几纳米就是生死的节点上，这一条裙子足以报废整层图形。")],-1)),(r(),o(n,null,{default:E(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E5%BA%95%E5%B1%82%E5%9B%BA%E5%8C%96%E7%A8%8B%E5%BA%A6%22%5D%20--%3E%20U%5B%22%E6%AC%A0%E5%9B%BA%E5%8C%96%22%5D%0A%20%20C%20--%3E%20OK%5B%22%E7%AA%97%E5%8F%A3%E5%86%85%22%5D%0A%20%20C%20--%3E%20O%5B%22%E8%BF%87%E5%9B%BA%E5%8C%96%E6%88%90%E7%8E%BB%E7%92%83%22%5D%0A%20%20U%20--%3E%20A1%5B%22%E8%A2%AB%E6%98%BE%E5%BD%B1%E6%B6%B2%E6%94%BB%E5%87%BB%22%5D%0A%20%20A1%20--%3E%20F1%5B%22%E7%95%8C%E9%9D%A2%E6%92%95%E5%BC%80%E3%80%81%E5%89%A5%E8%90%BD%22%5D%0A%20%20OK%20--%3E%20A2%5B%22%E9%94%9A%E4%B8%8E%E7%95%8C%E9%9D%A2%E8%83%BD%E5%8C%B9%E9%85%8D%22%5D%0A%20%20A2%20--%3E%20G1%5B%22%E5%9B%BE%E5%BD%A2%E4%BF%9D%E7%9C%9F%22%5D%0A%20%20O%20--%3E%20A3%5B%22%E6%9C%BA%E6%A2%B0%E9%94%9A%E5%B7%AE%E3%80%81%E5%BA%94%E5%8A%9B%E9%9B%86%E4%B8%AD%22%5D%0A%20%20A3%20--%3E%20F2%5B%22%E4%BB%8E%E5%BC%B1%E7%95%8C%E9%9D%A2%E6%95%B4%E7%89%87%E6%8E%80%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p>倒塌时，黏附力矩对抗毛细力矩。同样深宽比，黏附好可以多活一截；黏附课救不了深宽比预算本身——<a href="/litho/high-na-resist-budget">胶厚</a> 仍要薄。</p><p><span class="marginnote">金属衬底与低 k 介质表面能差很大，同一胶换层必须重做底涂，不能把前层资格复印。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写 HMDS 的分子式考据，不把某 BARC 牌号当标准。不重写驻波光学。下一课分子量改的是膜的内聚强度与溶解行为，从而改「撕在体内还是撕在界面」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>黏附是界面能与固化窗口，不是减反厚度的副产品。</li><li>剥落会伪装成缺孔；用重复性与剂量敏感拆开。</li><li>底涂与底层固化是资格项；过/欠都失败。</li><li>EUV 电子产额与黏附是不同账。</li><li>出处：BARC/underlayer 黏附通称；主干 <a href="/litho/euv-underlayer">EUV 底层</a>；Mack / Levinson 工艺叙述。</li></ul>',6))])}const b=A(p,[["render",h]]);export{_ as __pageData,b as default};
